struct Tree {
    typedef ll T;
    static constexpr T unit = 1e9;
    T f(T a, T b) { return min(a,b); }
    vector<T> s; ll n;
    Tree(ll n = 0, T def = unit) : s(2*n, def), n(n) {}
    void update(ll pos, T val) {
        for (s[pos += n] = val; pos /= 2;)
            s[pos] = f(s[pos * 2], s[pos * 2 + 1]);
    }
    T query(ll b, ll e) {
        ll ra = unit, rb = unit;
        for (b += n, e += n; b < e; b /= 2, e /= 2) {
            if (b % 2) ra = f(ra, s[b++]);
            if (e % 2) rb = f(s[--e], rb);
        }
        return f(ra, rb);
    }
    T val (ll x) {
        return query(x, x+1);
    }
};

