        }

        set<int> global_fixes;
        for (int i = 1; i <= m; i++) for (ll x : fixes[i]) global_fixes.insert(x);

        // segtree dp
        ll dp [n+1][2];
        dp[0][0] = 0; dp[0][1] = 0;
        // cout << dp[0][0] << " " << dp[0][1] << endl;

        Tree dpc (n+1); dpc.update(0, n);

